-- ============================================================
-- Palanote — Données de démonstration du club (soutenance)
--
-- Remplit le centre avec :
--   · 40 adhérents fictifs (adresses @example.org, numéros fictifs 06 39 98…) ;
--   · le stock du matériel (réservé par les sorties) ;
--   · l'inventaire pièce par pièce : 1 semi-rigide de 20 places, 40 blocs (30 × 12 L, 10 × 15 L)
--     avec TIV et requalification, 8 blocs de 3 L pour les recycleurs, 30 détendeurs,
--     20 combinaisons semi-étanches, 10 étanches, 4 recycleurs, 20 gilets, 10 ordinateurs.
-- Les dates sont calculées à partir d'aujourd'hui : quelques contrôles sont dépassés ou proches,
-- pour que les alertes apparaissent pendant la démo.
--
-- Prérequis : palanote-inventaire-materiel.sql, palanote-import-excel.sql, palanote-privilegies.sql.
-- Le centre visé : celui dont le nom contient « Lion » (sinon le premier centre créé).
-- Relançable : les données de démo précédentes sont remplacées (rien d'autre n'est touché).
-- ============================================================

do $demo$
declare
  v_centre uuid;
  v_stock uuid;
begin
  select id into v_centre from public.centres where nom ilike '%lion%' order by created_at limit 1;
  if v_centre is null then select id into v_centre from public.centres order by created_at limit 1; end if;
  if v_centre is null then raise exception 'aucun centre : crée d''abord ton centre dans l''app'; end if;

  -- On repart de zéro pour la démo (seulement les données marquées démo)
  delete from public.materiel_articles where centre_id = v_centre and caracteristiques ->> 'demo' = 'oui';
  delete from public.centre_adherents where centre_id = v_centre and email like '%@example.org';


  -- Stock réservé par les sorties : une ligne par type (créée ou mise à jour)
  create temporary table if not exists demo_stock (cle text primary key, id uuid) on commit drop;
  delete from demo_stock;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Le Lion (semi-rigide)') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'bateau', quantite = 1, places = 20 where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Bloc 12 L') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'bloc', quantite = 30, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Bloc 15 L') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'bloc', quantite = 10, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Bloc 3 L recycleur') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'bloc', quantite = 8, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Détendeur') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'detendeur', quantite = 30, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Combinaison semi-étanche 7 mm') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'combinaison', quantite = 20, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Combinaison étanche') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'combinaison', quantite = 10, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Recycleur') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'autre', quantite = 4, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Gilet stabilisateur') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'gilet', quantite = 20, places = null where id = v_stock;
  end if;
  select id into v_stock from public.materiel where centre_id = v_centre and deleted_at is null and lower(libelle) = lower('Ordinateur de plongée') limit 1;
  if v_stock is null then
  else
    update public.materiel set type = 'ordinateur', quantite = 10, places = null where id = v_stock;
  end if;

  -- Inventaire pièce par pièce

  -- Le stock prend la date du prochain contrôle le plus proche de ses pièces (alertes du tableau de bord)
  update public.materiel m set prochain_controle = x.prochain
  from (select materiel_id, min(least(coalesce(prochain_controle, prochaine_requalif), coalesce(prochaine_requalif, prochain_controle))) as prochain
        from public.materiel_articles where centre_id = v_centre and deleted_at is null and etat <> 'hors_service' group by materiel_id) x
  where m.id = x.materiel_id;

  raise notice 'Démo : 40 adhérents et % pièces de matériel pour le centre %', (select count(*) from public.materiel_articles where centre_id = v_centre and caracteristiques ->> 'demo' = 'oui'), v_centre;
end
$demo$;
